const {$,esc,fmt,api,toast,modal,closeModal}=window;
const state={page:'dashboard',projects:[],projectId:null,projectTab:'overview',candidateId:null,candidateSection:'evidence',candidateReturnTab:'candidates',providers:null,health:false,candidateQuery:'',candidateArchive:'active',candidateMaterial:'all',candidateStage:'all',candidatePage:0,candidateLimit:25,candidateRows:[],taskStatus:'',taskType:'',taskPage:0,taskLimit:50,cockpitPage:0,cockpitLimit:25,auditOffset:0,flowQuery:'',handoffPayload:null,jobSetupStep:1,jobSetupDraft:null,jobSetupSuggestions:[],criteriaStageDefs:[],criteriaRecruitmentContext:{},criteriaDecisionPolicy:{},criteriaBrief:{},criteriaOriginalByKey:{}};
// Ephemeral drafts survive in-flight workbench redraws but never leave this browser session.
const materialDrafts=new Map();
window.state=state;window.materialDrafts=materialDrafts;
// Inline event-handler attributes (onclick/onchange) resolve in global scope, but these page
// entry points are module-scoped. Expose them explicitly so injected handlers resolve;
// scripts/check_frontend_contract.py fails the source gate if a handler reference is unassigned.
window.renderPage=renderPage;window.projectWorkspace=projectWorkspace;
// Inline handlers also mutate module state; the wrappers below own that mutation so the
// attributes stay global-scope-safe. scripts/check_frontend_contract.py fails the gate
// on any handler that still references a module-scope binding directly.
window.selectFlowCandidate=el=>{state.candidateId=el.value;return projectWorkspace()};
window.filterCandidatesByStage=k=>{state.candidateStage=k;return setProjectTab('candidates')};
function statusClass(s){if(['succeeded','confirmed','published','ready','active','open','hired','accepted','completed','approved'].includes(s))return'good';if(['failed','rejected','conflict','declined','withdrawn','cancelled','closed'].includes(s))return'bad';if(['waiting_provider','draft','missing','partial','paused','offer','scheduled','shortlisted'].includes(s))return'warn';return'info'}
const stageLabels={new:'新候选人',screening:'简历筛选',shortlisted:'短名单',phone_screen:'电话筛选',interview:'面试',offer:'Offer',hired:'录用',rejected:'拒绝',talent_pool:'人才池',withdrawn:'候选人退出'};const projectStatusLabels={draft:'草案',open:'招聘中',paused:'暂停招聘',filled:'已招满',closed:'已关闭',archived:'已归档'};const offerLabels={draft:'草案',approved:'已批准',sent:'已发送',accepted:'已接受',declined:'已拒绝',withdrawn:'已撤回'};const offerNextStatuses={draft:['approved','withdrawn'],approved:['sent','withdrawn'],sent:['accepted','declined','withdrawn'],accepted:[],declined:[],withdrawn:[]};function stageLabel(s){return stageLabels[s]||s||'—'};const workbenchActionLabels={RESOLVE_CONFLICT:'处理证据冲突',VERIFY_CRITERION:'核实评价标准',RUN_SCREEN:'完成简历筛选',PREPARE_INTERVIEW:'准备结构化面试',REVIEW_REEVALUATION:'复核重新评价',MAKE_DECISION:'提交人工决定'};function workbenchActionLabel(s){return workbenchActionLabels[s]||s||'待处理'}
const icons={dashboard:'▦',projects:'▣',templates:'▤',knowledge:'⌕',tasks:'⟳',settings:'⚙'};
function shell(){return `<div class="app-shell"><aside class="sidebar"><div class="logo"><div class="logo-mark">SRW</div><div><strong>智能招聘工作台</strong><small>v1.0 Convergence 11 · Business Workflow Closure</small></div></div><div class="nav-group">Recruitment OS</div>${[['dashboard','工作台总览'],['projects','招聘项目'],['templates','岗位模板'],['knowledge','知识库'],['tasks','后台任务'],['settings','系统设置']].map(([k,l])=>`<button class="nav-item ${state.page===k?'active':''}" onclick="go('${k}')"><span class="nav-icon">${icons[k]}</span><span>${l}</span></button>`).join('')}<div class="side-footer">本地优先 · 业务闭环 · 证据可追溯<br>AI 建议 ≠ 人工决定<br><span id="side-health">正在检查服务…</span></div></aside><main class="main"><header class="topbar"><div class="top-title" id="top-title"></div><div class="top-right"><span id="service-health-badge" class="badge" role="status" aria-live="polite"><span id="service-health-dot" class="dot ${state.health?'good':''}"></span><span id="service-health-text">${state.health?'服务正常':'服务检查中'}</span></span><span class="badge">v1_0014</span></div></header><div class="content" id="content"></div></main></div>`}
window.go=async p=>{state.page=p;state.candidateId=null;state.candidateSection='evidence';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage()};window.openWorkbenchItem=async(pid,cid,type)=>{state.page='projects';state.projectId=pid;state.candidateReturnTab=type==='PREPARE_INTERVIEW'?'flow':'cockpit';state.projectTab=state.candidateReturnTab;state.candidateId=type==='PREPARE_INTERVIEW'?null:cid;state.candidateSection='evidence';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage()};window.openOperationalItem=async(kind,pid,cid,eid)=>{state.page='projects';state.projectId=pid;state.candidateReturnTab='overview';state.projectTab=kind==='pending_interview_feedback'?'flow':'overview';state.candidateId=['overdue_contact','today_contact'].includes(kind)?(cid||null):null;state.candidateSection='process';document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;await renderPage();if(['overdue_contact','today_contact'].includes(kind)&&cid)await openActionPlan(cid);if(kind==='pending_interview_feedback'&&eid)await openScorecards(eid)};window.openReviewItem=async(kind,pid,cid,reviewId='',claimId='')=>{
  state.page='projects';state.projectId=pid;state.candidateReturnTab='quality';
  state.projectTab=kind==='unreviewed_claim'?'candidates':'quality';
  state.candidateId=kind==='unreviewed_claim'?(cid||null):null;
  state.candidateSection='evidence';
  document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;
  await renderPage();
  const focusId=kind==='unreviewed_claim'?(claimId?'srw-claim-'+claimId:''):(reviewId?'srw-review-'+reviewId:'');
  if(!focusId)return;
  const target=document.getElementById(focusId);
  if(!target){toast('该复核项可能已处理或不在当前页面，请核对队列。',true);return}
  target.classList.add('review-item-focused');
  target.scrollIntoView({block:'center',behavior:'auto'});
  const button=target.querySelector('button');
  if(button)button.focus({preventScroll:true});
};
async function init(){document.body.innerHTML=shell()+`<div id="modal-root"></div><div id="toast-root"></div>`;try{await api('/health/ready');state.health=true}catch{}await renderPage();}
async function renderPage(){const t={dashboard:'工作台总览',projects:'招聘项目',templates:'岗位模板',knowledge:'知识库',tasks:'后台任务',settings:'系统设置'}[state.page]||'工作台';$('#top-title').textContent=t;if($('#side-health'))$('#side-health').textContent=state.health?'服务已就绪 · 本地数据':'服务状态待确认';const healthText=$('#service-health-text'),healthDot=$('#service-health-dot');if(healthText)healthText.textContent=state.health?'服务正常':'服务检查中';if(healthDot)healthDot.classList.toggle('good',Boolean(state.health));const fn={dashboard:window.dashboardPage,projects:projectsPage,templates:window.templatesPage,knowledge:window.knowledgePage,tasks:window.tasksPage,settings:window.settingsPage}[state.page];try{await fn()}catch(e){$('#content').innerHTML=`<div class="panel"><div class="panel-body empty"><strong>页面加载失败</strong>${esc(e.message)}</div></div>`}}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
async function projectsPage(){const d=await api('/api/v1/projects');state.projects=d.projects||[];if(state.projectId){return projectWorkspace()}$('#content').innerHTML=head('招聘项目','把每个招聘项目作为一条职位生命周期管理：草案 → 招聘中 → 暂停 / 招满 / 关闭。',`<button class="btn" onclick="c08OpenProjectImport()">导入完整项目包</button><button class="btn primary" onclick="openNewProject()">＋ 新建项目</button>`)+`<section class="panel"><div class="panel-head"><h2>职位生命周期</h2><span class="subtle">${state.projects.length} 个项目</span></div><div class="table-wrap"><table class="table"><thead><tr><th>项目 / 职位</th><th>招聘状态</th><th>标准</th><th>候选人</th><th>待办</th><th></th></tr></thead><tbody>${state.projects.length?state.projects.map(p=>`<tr><td><strong>${esc(p.title)}</strong><div class="subtle">${esc(p.protocol_title||'—')}</div></td><td><span class="status ${statusClass(p.status)}">${esc(projectStatusLabels[p.status]||p.status)}</span></td><td><span class="status ${statusClass(p.protocol_state)}">${esc(p.protocol_state)}</span></td><td>${p.candidate_count}</td><td>${p.open_work_count}</td><td class="right"><button class="btn small primary" onclick="openProject('${p.project_id}')">进入工作区</button></td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><strong>还没有招聘项目</strong>先新建职位，再发布招聘标准。</div></td></tr>`}</tbody></table></div></section>`}
window.openProject=async id=>{state.projectId=id;state.projectTab='overview';state.candidateId=null;state.candidateSection='evidence';await projectsPage()};window.closeProject=async()=>{state.projectId=null;state.candidateId=null;state.candidateSection='evidence';await projectsPage()};window.setProjectTab=async t=>{state.projectTab=t;state.candidateId=null;state.candidateSection='evidence';await projectWorkspace()};
function projectTabs(){return [['overview','项目首页'],['criteria','建岗与标准'],['candidates','候选人收件'],['cockpit','筛选与决策'],['flow','面试流程'],['ops','跟进运营'],['quality','质量复核'],['audit','版本与审计']].map(([k,l])=>`<button class="tab ${state.projectTab===k?'active':''}" onclick="setProjectTab('${k}')">${l}</button>`).join('')}
async function projectWorkspace(){const p=state.projects.find(x=>x.project_id===state.projectId)||{};if(state.candidateId){await candidateDrawer(state.candidateId,p);return}$('#content').innerHTML=`<div class="project-banner"><div><button class="btn small" onclick="closeProject()">← 返回项目列表</button><h2>${esc(p.title||'项目工作区')}</h2><div class="project-meta"><span class="badge">岗位：${esc(p.protocol_title||'—')}</span><span class="badge">状态：${esc(projectStatusLabels[p.status]||p.status||'—')}</span><span class="badge">协议：${esc(p.protocol_state||'—')}</span><span class="badge">候选人：${p.candidate_count||0}</span></div></div><div class="actions"><button class="btn" onclick="openProjectStatus('${p.status||'draft'}')">职位生命周期</button><button class="btn" onclick="archiveProject('${state.projectId}')">归档项目</button></div></div><div class="panel"><div class="tabs">${projectTabs()}</div><div class="panel-body" id="project-tab-body"><div class="empty">加载中…</div></div></div>`;const fn={overview:projectOverview,criteria:criteriaTab,cockpit:cockpitTab,candidates:candidatesTab,flow:flowTab,ops:async(el,p)=>window.operationsLearningTab(el,p),quality:qualityTab,audit:auditTab}[state.projectTab];try{await fn($('#project-tab-body'),p)}catch(e){$('#project-tab-body').innerHTML=`<div class="empty"><strong>加载失败</strong>${esc(e.message)}</div>`}}
window.openProjectStatus=current=>modal('职位生命周期',`<div class="field"><label>职位状态</label><select id="project-status" class="select">${[['draft','草案'],['open','招聘中'],['paused','暂停招聘'],['filled','已招满'],['closed','关闭职位']].map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>变更理由</label><textarea id="project-status-reason" class="textarea" placeholder="例如：HC 已批准 / 暂停招聘 / 已完成录用"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveProjectStatus()">确认变更</button>`);window.saveProjectStatus=async()=>{try{await api(`/api/v1/projects/${state.projectId}/status`,{method:'POST',body:JSON.stringify({status:$('#project-status').value,reason:$('#project-status-reason').value||'人工更新职位状态',actor:'human'})});closeModal();toast('职位状态已更新');await refreshProjects();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.archiveProject=async id=>{if(!confirm('归档该项目？数据不会删除。'))return;try{await api(`/api/v1/projects/${id}/archive`,{method:'POST'});state.projectId=null;toast('项目已归档');await projectsPage()}catch(e){toast(e.message,true)}};
async function projectOverview(el,p){const [pipe,proto]=await Promise.all([api(`/api/v1/projects/${state.projectId}/pipeline`),api(`/api/v1/projects/${state.projectId}/protocol-workspace`).catch(()=>null)]);const s=pipe.stages||{},o=pipe.offers_by_status||{};const w=pipe.workflow_summary||{next_action:{tab:'candidates',label:'继续推进候选人',reason:''}};el.innerHTML=`<div class="actions" style="margin-bottom:12px"><button class="btn primary" onclick="openContactWorkbench()">联系工作台</button><button class="btn" onclick="openRankedShortlist('${state.projectId}')">证据短名单</button><button class="btn" onclick="openProjectAiRuns('${state.projectId}')">AI 运行账本</button><button class="btn" onclick="openHandoff()">项目交接摘要</button><button class="btn" onclick="c08ExportProjectPackage('${state.projectId}')">完整项目包</button><a class="btn" href="/api/v1/projects/${state.projectId}/contact-list.csv">电话联系清单</a></div><div class="grid kpi">${[['候选人',pipe.total_candidates,'当前项目全部在库候选人'],['短名单',s.shortlisted||0,'待电话筛选 / 面试'],['近期面试',pipe.upcoming_interviews||0,'已排期未完成'],['Offer',Object.values(o).reduce((a,b)=>a+Number(b||0),0),'草案到接受的完整状态']].map(x=>`<div class="kpi-card"><div class="kpi-label">${x[0]}</div><div class="kpi-value">${x[1]}</div><div class="kpi-note">${x[2]}</div></div>`).join('')}</div><section class="panel"><div class="panel-head"><h3>招聘漏斗</h3><span class="status ${statusClass(pipe.project_status)}">${esc(projectStatusLabels[pipe.project_status]||pipe.project_status)}</span></div><div class="panel-body"><div class="funnel-grid">${['new','screening','shortlisted','phone_screen','interview','offer','hired'].map(k=>`<button class="funnel-step clickable" onclick="filterCandidatesByStage('${k}')"><strong>${s[k]||0}</strong><span>${stageLabel(k)}</span></button>`).join('')}</div><div class="pill-row" style="margin-top:12px"><span class="status info">人才池 ${s.talent_pool||0}</span><span class="status bad">拒绝 ${s.rejected||0}</span><span class="status">退出 ${s.withdrawn||0}</span></div></div></section><div class="two"><section class="panel"><div class="panel-head"><h3>近期面试</h3><button class="btn small" onclick="setProjectTab('flow')">招聘流程</button></div><div class="panel-body">${pipe.scheduled_events?.length?`<div class="quick-list">${pipe.scheduled_events.slice(0,6).map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.candidate_name)} · ${esc(x.title||x.event_type)}</div><div class="quick-note">${new Date(x.scheduled_at).toLocaleString()} · ${esc(x.interviewer||'待指定面试官')} · ${esc(x.location||'待指定地点')}</div></div><span class="status warn">已排期</span></div>`).join('')}</div>`:'<div class="empty">近期没有已排期面试</div>'}</div></section><section class="panel"><div class="panel-head"><div><h3>项目推进</h3><span class="subtle">系统根据当前真实业务状态给出一个优先动作，不替代人工招聘判断。</span></div></div><div class="panel-body"><div class="quick-list"><div class="quick-item"><span>招聘标准</span><strong>${w.criteria_published?'已发布':'待发布'}</strong></div><div class="quick-item"><span>候选人 / 缺材料</span><strong>${fmt(w.candidate_count||0)} / ${fmt(w.candidates_without_material||0)}</strong></div><div class="quick-item"><span>决策待办 / 待确认事实</span><strong>${fmt(w.decision_work_candidates||0)} / ${fmt(w.unreviewed_claims||0)}</strong></div><div class="quick-item"><span>待反馈面试 / 已排期</span><strong>${fmt(w.pending_interview_feedback||0)} / ${fmt(w.upcoming_interviews||0)}</strong></div><div class="quick-item"><span>Offer 待跟进</span><strong>${fmt(w.offer_followups||0)}</strong></div></div><div class="provider-card" style="margin-top:12px"><div class="provider-title"><div><h3>${esc(w.next_action?.label||'继续推进候选人')}</h3><div class="provider-sub">${esc(w.next_action?.reason||'')}</div></div><button class="btn primary" onclick="setProjectTab('${w.next_action?.tab||'candidates'}')">现在处理</button></div></div></div></section></div>`}
const defaultAssessmentStages=[
  {stage_key:'resume',name:'简历筛选',criteria:[]},
  {stage_key:'phone_screen',name:'电话筛选',criteria:[]},
  {stage_key:'interview',name:'面试',criteria:[]}
];

function criterionStageKeys(key){
  if(!key)return [];
  return (state.criteriaStageDefs||[]).filter(s=>(s.criteria||[]).includes(key)).map(s=>s.stage_key)
}

async function criteriaTab(el,p){
  const d=await api(`/api/v1/projects/${state.projectId}/protocol-workspace`);
  const active=d.draft||d.current||{};
  const criteria=active.criteria||[];
  state.criteriaOriginalByKey=Object.fromEntries(criteria.filter(x=>x&&typeof x==='object').map(x=>[String(x.criterion_key||x.key||''),{...x}]).filter(([k])=>k));
  state.criteriaBrief={...(active.brief||{})};
  state.criteriaRecruitmentContext={...(active.recruitment_context||{})};
  state.criteriaDecisionPolicy={...(active.decision_policy||{})};
  state.criteriaStageDefs=(active.assessment_stages?.length?active.assessment_stages:defaultAssessmentStages).map(s=>({...s,criteria:[...(s.criteria||[])]}));
  el.innerHTML=`<div class="actions" style="margin-bottom:12px"><button class="btn primary" onclick="openJobSetup()">四步建岗向导</button><button class="btn" onclick="suggestJobSetup()">知识/系统建议</button></div><div class="two criteria-layout"><div><div class="field"><label>岗位名称</label><input id="crit-title" class="input" value="${esc(active.brief?.title||p.protocol_title||'')}"></div><div class="field" style="margin-top:10px"><label>岗位摘要 / JD</label><textarea id="crit-summary" class="textarea">${esc(active.brief?.summary||'')}</textarea></div><div class="divider"></div><div class="panel-head" style="padding:0 0 10px;border:0"><div><h3>评价标准</h3><span class="subtle">权重只在证据闭合后参与诊断性匹配投影；缺失或冲突证据不会按 0 分处理。</span></div><button class="btn small" onclick="addCriterionRow()">＋ 添加标准</button></div><div id="criteria-rows">${criteria.map((x,i)=>criterionRow(x,i,criterionStageKeys(x.criterion_key||x.key||''))).join('')}</div><div class="actions" style="margin-top:12px"><button class="btn primary" onclick="saveCriteria('${d.draft_revision_id||''}')">保存草案</button>${d.draft_revision_id?`<button class="btn" onclick="publishCriteria('${d.draft_revision_id}')">发布当前标准</button>`:`<button class="btn" onclick="forkDraft()">基于当前版本创建新草案</button>`}</div></div><div><div class="provider-card"><h3>标准设计约束</h3><p class="subtle">“必须核实”与“决策关键”会决定 Candidate Workspace 的阻塞项。阶段分配用于说明在哪个招聘环节核实该标准；一个标准可以属于多个阶段。</p><div class="divider"></div><div class="pill-row"><span class="status info">Missing ≠ 0</span><span class="status info">AI ≠ Decision</span><span class="status info">版本可追溯</span><span class="status info">保存 ≠ 发布</span></div></div><div class="provider-card" style="margin-top:12px"><h3>草案完整性</h3><div class="quick-list"><div class="quick-item"><span>建岗上下文</span><strong>${Object.keys(state.criteriaRecruitmentContext).length?'保留':'尚未填写'}</strong></div><div class="quick-item"><span>评价阶段</span><strong>${state.criteriaStageDefs.length} 个</strong></div><div class="quick-item"><span>发布边界</span><strong>必须人工显式发布</strong></div></div></div></div></div>`
}

function criterionRow(x={},i=0,stageKeys=[]){
  const key=x.criterion_key||x.key||'';
  const weight=Number(x.weight??1);
  const stages=(state.criteriaStageDefs?.length?state.criteriaStageDefs:defaultAssessmentStages);
  return `<div class="criterion-card criterion-row" data-i="${i}" data-criterion-key="${esc(key)}"><div class="criterion-card-head"><div><strong>${esc(x.name||'新评价标准')}</strong><span class="mono subtle">${esc(key||'保存时生成稳定 ID')}</span></div><button class="btn small danger" onclick="this.closest('.criterion-row').remove()">删除</button></div><div class="form-grid"><div class="field"><label>标准名称</label><input class="input c-name" value="${esc(x.name||'')}"></div><div class="field"><label>权重</label><input class="input c-weight" type="number" min="0.01" step="0.1" value="${Number.isFinite(weight)&&weight>0?weight:1}"></div><div class="field full"><label>标准定义 / 判断口径</label><textarea class="textarea c-definition" placeholder="说明什么证据可支持“满足 / 部分满足 / 未满足”">${esc(x.definition||'')}</textarea></div><div class="field full"><label>核实问题</label><input class="input c-probe" value="${esc((x.verification_probes||[])[0]||'')}" placeholder="缺证据时，TA / 面试官应该问什么？"></div></div><div class="criterion-stage-box"><small>核实阶段</small><div class="pill-row">${stages.map(s=>`<label class="stage-check"><input type="checkbox" class="c-stage" value="${esc(s.stage_key)}" ${stageKeys.includes(s.stage_key)?'checked':''}> ${esc(s.name||s.stage_key)}</label>`).join('')}</div></div><div class="pill-row" style="margin-top:10px"><label><input type="checkbox" class="c-critical" ${x.decision_critical?'checked':''}> 决策关键</label><label><input type="checkbox" class="c-verify" ${x.verification_required?'checked':''}> 必须核实</label></div></div>`
}

window.addCriterionRow=()=>{
  $('#criteria-rows').insertAdjacentHTML('beforeend',criterionRow({},document.querySelectorAll('.criterion-row').length,[]))
};

function ensureCriterionKey(row){
  let key=(row.dataset.criterionKey||'').trim();
  if(!key){
    key=(globalThis.crypto?.randomUUID?.()||('criterion-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8)));
    row.dataset.criterionKey=key
  }
  return key
}

function collectCriteria(){
  return [...document.querySelectorAll('.criterion-row')].map(r=>{
    const name=r.querySelector('.c-name').value.trim();
    if(!name)return null;
    const weight=Number(r.querySelector('.c-weight').value||1);
    if(!Number.isFinite(weight)||weight<=0)throw new Error(`“${name}”的权重必须大于 0`);
    const criterion_key=ensureCriterionKey(r);
    return {
      ...(state.criteriaOriginalByKey[criterion_key]||{}),
      criterion_key,
      name,
      definition:r.querySelector('.c-definition').value.trim(),
      weight,
      decision_critical:r.querySelector('.c-critical').checked,
      verification_required:r.querySelector('.c-verify').checked,
      verification_probes:[r.querySelector('.c-probe').value.trim()].filter(Boolean)
    }
  }).filter(Boolean)
}

function collectAssessmentStages(criteria){
  const valid=new Set(criteria.map(x=>x.criterion_key));
  const defs=(state.criteriaStageDefs?.length?state.criteriaStageDefs:defaultAssessmentStages).map(s=>({...s,criteria:[]}));
  const byKey=new Map(defs.map(s=>[s.stage_key,s]));
  for(const row of document.querySelectorAll('.criterion-row')){
    const key=ensureCriterionKey(row);
    if(!valid.has(key))continue;
    for(const input of row.querySelectorAll('.c-stage:checked')){
      const stage=byKey.get(input.value);
      if(stage&&!stage.criteria.includes(key))stage.criteria.push(key)
    }
  }
  return defs
}

window.saveCriteria=async rid=>{
  try{
    if(!rid){toast('请先创建草案',true);return}
    const criteria=collectCriteria();
    const payload={
      brief:{...state.criteriaBrief,title:$('#crit-title').value,summary:$('#crit-summary').value},
      criteria,
      assessment_stages:collectAssessmentStages(criteria),
      decision_policy:{...state.criteriaDecisionPolicy,human_final:true},
      recruitment_context:{...state.criteriaRecruitmentContext}
    };
    await api(`/api/v1/protocol-revisions/${rid}`,{method:'PATCH',body:JSON.stringify({payload,provenance:{ui:'business-convergence11-product-workflow'}})});
    toast('草案已保存；建岗上下文、阶段分配与决策策略已保留');
    await projectWorkspace()
  }catch(e){toast(e.message,true)}
};

window.publishCriteria=async rid=>{if(!confirm('发布后将成为候选人评价的当前标准，确认发布？'))return;try{await api(`/api/v1/protocol-revisions/${rid}/publish`,{method:'POST'});toast('招聘标准已发布');await refreshProjects();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.forkDraft=async()=>{try{await api(`/api/v1/projects/${state.projectId}/protocol-drafts`,{method:'POST'});toast('已创建新草案');await projectWorkspace()}catch(e){toast(e.message,true)}};

async function cockpitTab(el,p){const d=await api(`/api/v1/projects/${state.projectId}/cockpit?limit=${state.cockpitLimit}&offset=${state.cockpitPage*state.cockpitLimit}`);const pages=Math.max(1,Math.ceil(d.total/state.cockpitLimit));el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><div><h3>决策驾驶舱 <span class="subtle">${d.total} 人</span></h3><span class="subtle">服务端分页聚合；流程阶段与证据记录分开呈现。</span></div><button class="btn primary" onclick="openRankedShortlist('${state.projectId}')">生成证据短名单</button></div><div class="table-wrap"><table class="table"><thead><tr><th>候选人</th><th>阶段</th><th>岗位匹配</th><th>证据覆盖</th><th>材料</th><th>已确认事实</th><th>待确认</th><th>当前判断项</th><th></th></tr></thead><tbody>${d.candidates.map(c=>`<tr><td><strong>${esc(c.display_name)}</strong></td><td><span class="status ${statusClass(c.pipeline_stage)}">${stageLabel(c.pipeline_stage)}</span></td><td>${c.assessment?.fit_score==null?'<span class="subtle">待证据闭合</span>':`<strong>${c.assessment.fit_score}%</strong>`}</td><td>${c.assessment?`${Math.round(Number(c.assessment.evidence_coverage||0)*100)}%`:'—'}</td><td>${c.has_material?'已导入':'待上传'}</td><td>${c.confirmed_claims}</td><td>${c.unreviewed_claims}</td><td>${c.judgments}</td><td><button class="btn small primary" onclick="openCandidate('${c.candidate_id}')">查看工作区</button></td></tr>`).join('')}</tbody></table></div><div class="actions" style="justify-content:flex-end;margin-top:12px"><button class="btn small" ${state.cockpitPage<=0?'disabled':''} onclick="cockpitPage(-1)">上一页</button><span class="subtle">第 ${state.cockpitPage+1} / ${pages} 页</span><button class="btn small" ${(state.cockpitPage+1)>=pages?'disabled':''} onclick="cockpitPage(1)">下一页</button></div>`}
window.cockpitPage=d=>{state.cockpitPage=Math.max(0,state.cockpitPage+d);projectWorkspace()};
async function candidatesTab(el,p){const qs=new URLSearchParams({archived:state.candidateArchive,material:state.candidateMaterial,stage:state.candidateStage,limit:String(state.candidateLimit),offset:String(state.candidatePage*state.candidateLimit)});if(state.candidateQuery.trim())qs.set('q',state.candidateQuery.trim());const d=await api(`/api/v1/projects/${state.projectId}/candidates?${qs.toString()}`);state.candidateRows=d.candidates;const pages=Math.max(1,Math.ceil(d.total/state.candidateLimit));el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><h3>候选人 Pipeline <span class="subtle">${d.total} 人</span></h3><div class="actions"><button class="btn" onclick="bulkImport()">批量导入简历</button><a class="btn" href="/api/v1/projects/${state.projectId}/candidates.csv" download>导出 CSV</a><button class="btn" onclick="compareSelected()">对比 2–5 人</button><button class="btn primary" onclick="openAddCandidate()">＋ 新增候选人</button></div></div><div class="searchbar"><div class="field"><label>搜索候选人</label><input id="cand-q" class="input" value="${esc(state.candidateQuery)}" placeholder="姓名 / 显示名称"></div><div class="field"><label>候选人阶段</label><select id="cand-stage" class="select"><option value="all">全部阶段</option>${Object.entries(stageLabels).map(([v,l])=>`<option value="${v}" ${state.candidateStage===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>归档筛选</label><select id="cand-archive" class="select"><option value="active" ${state.candidateArchive==='active'?'selected':''}>在库</option><option value="archived" ${state.candidateArchive==='archived'?'selected':''}>已归档</option><option value="all" ${state.candidateArchive==='all'?'selected':''}>全部</option></select></div><div class="field"><label>材料筛选</label><select id="cand-material" class="select"><option value="all" ${state.candidateMaterial==='all'?'selected':''}>全部</option><option value="with" ${state.candidateMaterial==='with'?'selected':''}>已有材料</option><option value="without" ${state.candidateMaterial==='without'?'selected':''}>待导入材料</option></select></div><div class="actions" style="align-self:end"><button class="btn primary" onclick="applyCandidateFilters()">应用筛选</button></div></div><div class="pipeline-toolbar"><span>批量推进：</span>${[['shortlisted','短名单'],['phone_screen','电话筛选'],['interview','面试'],['rejected','拒绝'],['talent_pool','人才池']].map(([v,l])=>`<button class="btn small" onclick="bulkStage('${v}')">${l}</button>`).join('')}</div><div class="table-wrap"><table class="table"><thead><tr><th></th><th>候选人</th><th>阶段</th><th>材料</th><th>创建时间</th><th></th></tr></thead><tbody>${d.candidates.length?d.candidates.map(c=>`<tr><td><input type="checkbox" class="cand-check" value="${c.candidate_id}" ${c.archived?'disabled':''}></td><td><strong>${esc(c.display_name)}</strong><div class="mono subtle">${esc(c.candidate_id)}</div></td><td><span class="status ${statusClass(c.pipeline_stage)}">${stageLabel(c.pipeline_stage)}</span></td><td><span class="status ${c.has_material?'good':'warn'}">${c.has_material?'当前材料已发布':'待导入'}</span></td><td>${new Date(c.created_at).toLocaleString()}</td><td class="right"><button class="btn small primary" onclick="openCandidate('${c.candidate_id}')">${c.has_material?'工作区':'导入材料'}</button> ${c.archived?(c.merged_into_candidate_id?`<span class="status info">已并入 canonical identity</span>`:`<button class="btn small" onclick="restoreCandidate('${c.candidate_id}')">恢复</button>`):`<button class="btn small" onclick="archiveCandidate('${c.candidate_id}')">归档</button>`}</td></tr>`).join(''):`<tr><td colspan="6"><div class="empty"><strong>没有符合条件的候选人</strong>调整筛选条件，或批量导入新的简历材料。</div></td></tr>`}</tbody></table></div><div class="actions" style="justify-content:flex-end;margin-top:12px"><button class="btn small" ${state.candidatePage<=0?'disabled':''} onclick="candidatePage(-1)">上一页</button><span class="subtle">第 ${state.candidatePage+1} / ${pages} 页</span><button class="btn small" ${(state.candidatePage+1)>=pages?'disabled':''} onclick="candidatePage(1)">下一页</button></div><input id="bulk-files" type="file" multiple hidden accept=".pdf,.docx,.xlsx,.txt,.md,.csv,.png,.jpg,.jpeg,.mp3,.wav,.m4a,.mp4,.webm">`}
window.applyCandidateFilters=()=>{state.candidateQuery=$('#cand-q')?.value||'';state.candidateArchive=$('#cand-archive')?.value||'active';state.candidateMaterial=$('#cand-material')?.value||'all';state.candidateStage=$('#cand-stage')?.value||'all';state.candidatePage=0;projectWorkspace()};window.candidatePage=delta=>{state.candidatePage=Math.max(0,state.candidatePage+delta);projectWorkspace()};window.openAddCandidate=()=>modal('新增候选人',`<div class="field"><label>候选人姓名 / 显示名称</label><input id="cand-name" class="input" placeholder="例如：张三"></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="createCandidate()">创建</button>`);
window.bulkStage=async stage=>{const ids=[...document.querySelectorAll('.cand-check:checked')].map(x=>x.value);if(!ids.length){toast('请先选择候选人',true);return}const reason=prompt(`批量推进到“${stageLabel(stage)}”的理由：`,'人工批量推进');if(reason===null)return;try{const r=await api(`/api/v1/projects/${state.projectId}/candidates/stage`,{method:'POST',body:JSON.stringify({candidate_ids:ids,stage,reason,actor:'human'})});toast(`批量推进：成功 ${r.updated}，失败 ${r.failed}`,r.failed>0);await projectWorkspace()}catch(e){toast(e.message,true)}};
window.createCandidate=async()=>{try{const r=await api(`/api/v1/projects/${state.projectId}/candidates`,{method:'POST',body:JSON.stringify({display_name:$('#cand-name').value})});closeModal();toast('候选人已创建');await openCandidate(r.candidate_id)}catch(e){toast(e.message,true)}};
window.archiveCandidate=async id=>{await api(`/api/v1/candidates/${id}/archive`,{method:'POST'});toast('候选人已归档');await projectWorkspace()};window.restoreCandidate=async id=>{await api(`/api/v1/candidates/${id}/restore`,{method:'POST'});toast('候选人已恢复');await projectWorkspace()};
window.bulkImport=()=>{const i=$('#bulk-files');i.onchange=async()=>{const files=[...i.files];if(!files.length)return;if(files.length>50){toast(`一次最多提交 50 份材料；当前选择 ${files.length} 份，请分批提交。`,true);i.value='';return}try{toast(`正在收件并创建后台任务：${files.length} 份材料…`);const items=[];for(const f of files){items.push({display_name:f.name.replace(/\.[^.]+$/,''),filename:f.name,media_type:f.type||'application/octet-stream',base64:await fileToBase64(f)})}const r=await api(`/api/v1/projects/${state.projectId}/candidates/batch-intake`,{method:'POST',body:JSON.stringify({items})});toast(`后台任务已提交：${r.item_count} 份材料 · Task ${String(r.task_id).slice(0,8)}…`);state.candidatePage=0;await projectWorkspace()}catch(e){toast(e.message,true)}finally{i.value=''}};i.click()};
window.compareSelected=async()=>{const ids=[...document.querySelectorAll('.cand-check:checked')].map(x=>x.value);if(ids.length<2||ids.length>5){toast('请选择 2–5 位候选人',true);return}try{const d=await api(`/api/v1/candidates/compare?ids=${encodeURIComponent(ids.join(','))}`);const heads=d.candidates.map(x=>`<th>${esc(x.display_name)}<small>${stageLabel(x.pipeline_stage)} · ${esc(offerLabels[x.offer_status]||x.offer_status||'无 Offer')} · Fit ${x.assessment?.fit_score==null?'待证据闭合':x.assessment.fit_score+'%'} · Evidence ${Math.round(Number(x.assessment?.evidence_coverage||0)*100)}%</small></th>`).join('');const body=d.criteria.map(cr=>`<tr><td><strong>${esc(cr.name)}</strong>${cr.decision_critical?'<div class="subtle">硬条件/关键项</div>':''}</td>${d.candidates.map(x=>{const j=x.criteria.find(v=>v.criterion_key===cr.criterion_key)||{};return `<td><span class="status ${statusClass(j.status)}">${esc(j.status||'missing')}</span><div>${esc(j.evidence_level||'none')}</div><div class="subtle">${esc(j.gap||j.reason||'—')}</div></td>`}).join('')}</tr>`).join('');modal('同岗位 · 当前标准版本候选人对比',`<p class="subtle">Protocol ${esc(d.protocol_revision_id)}。仅比较当前评价上下文，不按历史记录数量排名。</p><table class="table"><thead><tr><th>评价标准</th>${heads}</tr></thead><tbody>${body}</tbody></table><div class="divider"></div><div class="grid">${d.candidates.map(x=>`<div class="quick-item"><div><strong>${esc(x.display_name)}</strong><div class="quick-note">${esc(x.contact.email||'未录邮箱')} · ${esc(x.contact.phone||'未录电话')}</div></div></div>`).join('')}</div>`)}catch(e){toast(e.message,true)}};
window.openCandidate=async id=>{state.candidateReturnTab=state.projectTab||'candidates';state.candidateId=id;state.candidateSection='evidence';await candidateDrawer(id)};window.closeCandidateWorkspace=async()=>{state.candidateId=null;state.candidateSection='evidence';state.projectTab=state.candidateReturnTab||'candidates';await projectWorkspace()};window.setCandidateSection=async section=>{state.candidateSection=section;await candidateDrawer(state.candidateId)};window.openCandidateProjectFlow=async()=>{state.candidateId=null;state.projectTab='flow';await projectWorkspace()};
async function fileToBase64(file){return await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(file)})}
async function uploadFile(cid,file){const b64=await fileToBase64(file);return api(`/api/v1/candidates/${cid}/files`,{method:'POST',body:JSON.stringify({filename:file.name,media_type:file.type||'application/octet-stream',base64:b64,source_kind:'resume'})})}
function candidateEventsHtml(cid,ev){const rows=ev?.events||[];return `<section class="panel"><div class="panel-head"><div><h3>电话筛选与面试</h3><span class="subtle">排期、完成记录和独立 Scorecard 都保留在候选人上下文中。</span></div><div class="actions"><button class="btn small" onclick="openEvent('${cid}','phone_screen')">＋ 电话筛选</button><button class="btn small primary" onclick="openEvent('${cid}','interview')">＋ 面试排期</button></div></div><div class="panel-body">${rows.length?`<div class="timeline">${rows.map(x=>`<div class="timeline-item"><strong>${esc(x.title||x.event_type)} <span class="status ${statusClass(x.event_state)}">${esc(x.event_state)}</span></strong><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():new Date(x.created_at).toLocaleString()} · ${x.duration_minutes||0} 分钟 · ${esc(x.interviewer||'未指定')}</small><div>${esc(x.notes||'')}</div><div class="subtle">地点：${esc(x.location||'—')} · outcome：${esc(x.outcome||'—')}</div><div class="actions" style="margin-top:6px">${x.event_type==='interview'?`<button class="btn small" onclick="openScorecards('${x.event_id}')">独立 Scorecard</button>`:''}${x.event_state==='scheduled'?`<button class="btn small primary" onclick="completeEvent('${x.event_id}')">完成并反馈</button><button class="btn small" onclick="cancelEvent('${x.event_id}')">取消</button>`:''}</div></div>`).join('')}</div>`:'<div class="empty"><strong>暂无电话/面试记录</strong>可以直接为该候选人创建电话筛选或结构化面试。</div>'}</div></section>`}

function candidateReevaluationHtml(cid,re){const rows=re?.drafts||[];return `<section class="panel"><div class="panel-head"><div><h3>复评与上下文变化</h3><span class="subtle">复评草案不会自动覆盖人工决定。</span></div><button class="btn small primary" onclick="openReeval('${cid}')">＋ 复评草案</button></div><div class="panel-body">${rows.length?`<div class="quick-list">${rows.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.summary||'复评草案')}</div><div class="quick-note">${esc(x.state)} · ${new Date(x.created_at).toLocaleString()}</div></div>${x.state==='draft'?`<button class="btn small" onclick="applyReeval('${x.draft_id}')">查看/应用差异</button>`:''}</div>`).join('')}</div>`:'<div class="empty">暂无复评草案</div>'}</div></section>`}

async function candidateDrawer(cid,p=null){
  if(!cid)return;
  state.candidateId=cid;
  p=p||state.projects.find(x=>x.project_id===state.projectId)||{};
  const [contact,pipe,offers,actionPlan,events,reevaluations,w]=await Promise.all([
    api(`/api/v1/candidates/${cid}/contact`),
    api(`/api/v1/candidates/${cid}/pipeline`),
    api(`/api/v1/candidates/${cid}/offers`),
    api(`/api/v1/candidates/${cid}/action-plan`).catch(()=>null),
    api(`/api/v1/candidates/${cid}/events`).catch(()=>({events:[]})),
    api(`/api/v1/candidates/${cid}/reevaluations`).catch(()=>({drafts:[]})),
    api(`/api/v1/candidates/${cid}/workspace`).catch(()=>null)
  ]);
  // A just-created candidate has no published material/decision context;
  // requesting an assessment then raises an expected 409. Avoid that
  // unnecessary backend call while still showing Source intake.
  const assessment=w?.decision_context_hash?await api(`/api/v1/candidates/${cid}/assessment`).catch(()=>null):null;
  const latest=offers.offers?.[0],section=state.candidateSection||'evidence';
  const evidenceBody=`${w?candidateWorkspaceHtml(w,assessment):'<div class="empty"><strong>尚无当前材料</strong>先上传简历、扫描件或录音。支持 PDF/DOCX/XLSX/TXT/图片/OCR/音频/ASR。</div>'}<div class="divider"></div><div class="two"><div class="field"><label>粘贴文本材料</label><textarea id="paste-material" class="textarea" placeholder="简历文本、电话记录、补充材料" oninput="cacheMaterialDraft('${cid}',this.value)">${esc(materialDrafts.get(cid)||'')}</textarea><button class="btn" onclick="pasteMaterial('${cid}')">保存并发布材料版本</button></div><div class="field"><label>上传文件 / OCR / ASR</label><input id="candidate-file" class="input" type="file" accept=".pdf,.docx,.xlsx,.txt,.md,.csv,.png,.jpg,.jpeg,.mp3,.wav,.m4a,.mp4,.webm"><button class="btn primary" onclick="uploadCandidateFile('${cid}')">上传并处理</button><small class="subtle">图片和扫描 PDF 走 OCR；音频/视频走 ASR。Provider 未配置时原文件仍会保存。</small></div></div>`;
  const processBody=`<div class="candidate-process-grid"><section class="panel"><div class="panel-head"><h3>联系方式与跟进</h3><div class="actions"><button class="btn small" onclick="openContact('${cid}')">编辑联系方式</button><button class="btn small primary" onclick="openActionPlan('${cid}')">编辑下一步</button></div></div><div class="panel-body"><div class="quick-list"><div class="quick-item"><span>电话</span><strong>${esc(contact.phone||'未录入')}</strong></div><div class="quick-item"><span>邮箱</span><strong>${esc(contact.email||'未录入')}</strong></div><div class="quick-item"><span>人工确认</span><strong>${contact.user_confirmed?'已确认':'待确认'}</strong></div><div class="quick-item"><span>联系优先级 / 负责人</span><strong>${esc(actionPlan?.priority||'normal')} · ${esc(actionPlan?.owner||'未指定')}</strong></div><div class="quick-item"><span>联系状态</span><strong>${esc(actionPlan?.contact_status||'to_contact')}</strong></div><div class="quick-item"><span>下次联系</span><strong>${esc(actionPlan?.next_contact_at||'未安排')}</strong></div></div><p class="subtle" style="margin-bottom:0">${esc(actionPlan?.reason||'尚未填写下一步说明')}</p><div class="actions" style="margin-top:12px"><button class="btn" onclick="openPhoneScript('${cid}')">电话脚本 / 核实思路</button><button class="btn" onclick="openCandidateProjectFlow()">项目级招聘流程</button></div></div></section><section class="panel"><div class="panel-head"><h3>Pipeline 历史</h3><span class="status ${statusClass(pipe.current_stage)}">${stageLabel(pipe.current_stage)}</span></div><div class="panel-body">${pipe.transitions.length?`<div class="timeline">${pipe.transitions.slice().reverse().map(x=>`<div class="timeline-item"><strong>${stageLabel(x.from_stage)} → ${stageLabel(x.to_stage)}</strong><small>${esc(x.actor)} · ${new Date(x.created_at).toLocaleString()}</small><div class="subtle">${esc(x.reason||'')}</div></div>`).join('')}</div>`:'<div class="empty">尚无阶段变更</div>'}</div></section></div><div class="two">${candidateEventsHtml(cid,events)}${candidateReevaluationHtml(cid,reevaluations)}</div>`;
  const offerBody=`<section class="panel"><div class="panel-head"><div><h3>Offer 管理</h3><span class="subtle">Offer 状态与候选人 Pipeline 分开记录；接受 Offer 不会自动改写录用决定。</span></div><button class="btn primary" onclick="openOffer('${cid}')" ${['interview','offer'].includes(pipe.current_stage)?'':'disabled title="候选人需进入面试或 Offer 阶段"'}>＋ 创建 Offer</button></div><div class="panel-body">${offers.offers?.length?`<div class="quick-list">${offers.offers.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.title)} · ${esc(offerLabels[x.status]||x.status)}</div><div class="quick-note">目标入职：${esc(x.target_start_date||'待定')} · ${esc(x.compensation_note||'暂无薪酬说明')}</div></div><button class="btn small" onclick="openOfferStatus('${x.offer_id}','${x.status}','${cid}')" ${offerNextStatuses[x.status]?.length?'':'disabled title="Offer 已处于终态"'}>更新状态</button></div>`).join('')}</div>`:'<div class="empty"><strong>尚无 Offer</strong>候选人进入面试或 Offer 阶段后，可在这里创建并跟踪草案、批准、发送和接受状态。</div>'}</div></section>`;
  const sectionBody=section==='process'?processBody:section==='offer'?offerBody:`<section class="panel"><div class="panel-head"><div><h3>证据与判断</h3><span class="subtle">材料、Claim、评价标准、人工核实与最终人工决定集中在同一工作面。</span></div>${w?`<button class="btn primary" onclick="extractAllClaims('${cid}')">AI 提取当前材料事实</button>`:''}</div><div class="panel-body">${evidenceBody}</div></section>`;
  $('#content').innerHTML=`<div class="candidate-workspace-page"><div class="candidate-workspace-breadcrumb"><button class="btn small" onclick="closeCandidateWorkspace()">← 返回项目工作区</button><span class="subtle">${esc(p.title||'招聘项目')} / 候选人</span></div><div class="candidate-workspace-head"><div><div class="pill-row"><span class="status ${statusClass(pipe.current_stage)}">${stageLabel(pipe.current_stage)}</span>${w?.readiness_label?`<span class="status info">${esc(w.readiness_label)}</span>`:''}</div><h1>${esc(contact.display_name)}</h1><div class="subtle">${esc(contact.phone||'未录电话')} · ${esc(contact.email||'未录邮箱')} · ${contact.user_confirmed?'联系方式已人工确认':'联系方式待人工确认'}</div></div><div class="actions"><button class="btn" onclick="openCandidateBrief('${cid}')">候选人简报</button><button class="btn" onclick="openContact('${cid}')">联系方式</button><button class="btn" onclick="openActionPlan('${cid}')">行动计划</button><button class="btn primary" onclick="openStage('${cid}','${pipe.current_stage}')">推进阶段</button></div></div><div class="candidate-summary-strip"><div><small>当前阶段</small><strong>${stageLabel(pipe.current_stage)}</strong></div><div><small>决策状态</small><strong>${esc(w?.readiness_label||'待材料/标准')}</strong></div><div><small>当前决定</small><strong>${esc(w?.decision_label||'未决定')}</strong></div><div><small>Offer</small><strong>${latest?esc(offerLabels[latest.status]||latest.status):'尚无 Offer'}</strong></div><div><small>下次联系</small><strong>${esc(actionPlan?.next_contact_at||'未安排')}</strong></div></div><div class="candidate-workspace-tabs"><button class="candidate-workspace-tab ${section==='evidence'?'active':''}" onclick="setCandidateSection('evidence')">证据与判断${w?.blocking_count?` · ${w.blocking_count} 阻塞`:''}</button><button class="candidate-workspace-tab ${section==='process'?'active':''}" onclick="setCandidateSection('process')">流程与跟进${events.events?.length?` · ${events.events.length} 记录`:actionPlan?.next_contact_at?' · 已安排':''}</button><button class="candidate-workspace-tab ${section==='offer'?'active':''}" onclick="setCandidateSection('offer')">Offer${offers.offers?.length?` · ${offers.offers.length}`:''}</button></div><div class="candidate-workspace-content">${sectionBody}</div></div>`}

window.openContact=async cid=>{try{const c=await api(`/api/v1/candidates/${cid}/contact`);modal('候选人联系方式',`<div class="form-grid"><div class="field"><label>姓名</label><input id="ct-name" class="input" value="${esc(c.display_name)}"></div><div class="field"><label>电话</label><input id="ct-phone" class="input" value="${esc(c.phone)}"></div><div class="field full"><label>邮箱</label><input id="ct-email" class="input" value="${esc(c.email)}"></div><label class="field full"><span>人工确认</span><span><input id="ct-confirm" type="checkbox" ${c.user_confirmed?'checked':''}> 我已人工核对以上联系方式</span></label></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveContact('${cid}')">保存</button>`)}catch(e){toast(e.message,true)}};window.saveContact=async cid=>{try{await api(`/api/v1/candidates/${cid}/contact`,{method:'PATCH',body:JSON.stringify({display_name:$('#ct-name').value,phone:$('#ct-phone').value,email:$('#ct-email').value,user_confirmed:$('#ct-confirm').checked,actor:'human'})});toast('联系方式已保存');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.openStage=(cid,current)=>modal('候选人阶段',`<div class="field"><label>当前阶段</label><div class="status ${statusClass(current)}">${stageLabel(current)}</div></div><div class="field" style="margin-top:10px"><label>推进到</label><select id="stage-next" class="select">${Object.entries(stageLabels).map(([v,l])=>`<option value="${v}" ${v===current?'selected':''}>${l}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>人工理由</label><textarea id="stage-reason" class="textarea"></textarea></div><p class="subtle">阶段推进属于人工业务动作。AI 不能自动改变 Pipeline。</p>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveStage('${cid}')">确认推进</button>`);window.saveStage=async cid=>{try{await api(`/api/v1/candidates/${cid}/stage`,{method:'POST',body:JSON.stringify({stage:$('#stage-next').value,reason:$('#stage-reason').value||'人工推进',actor:'human'})});toast('候选人阶段已更新');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.openOffer=cid=>modal('创建 Offer',`<div class="form-grid"><div class="field"><label>Offer 职位</label><input id="offer-title" class="input"></div><div class="field"><label>目标入职日</label><input id="offer-start" class="input" type="date"></div><div class="field full"><label>薪酬说明</label><input id="offer-comp" class="input" placeholder="base + bonus / 薪酬范围"></div><div class="field full"><label>其他条款</label><textarea id="offer-terms" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveOffer('${cid}')">创建 Offer 草案</button>`);window.saveOffer=async cid=>{try{await api(`/api/v1/candidates/${cid}/offers`,{method:'POST',body:JSON.stringify({title:$('#offer-title').value,compensation_note:$('#offer-comp').value,target_start_date:$('#offer-start').value,terms:$('#offer-terms').value,actor:'human'})});toast('Offer 草案已创建');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};window.openOfferStatus=(oid,current,cid)=>modal('更新 Offer 状态',`<div class="field"><label>Offer 状态</label><select id="offer-status" class="select"><option value="">请选择下一状态</option>${(offerNextStatuses[current]||[]).map(v=>`<option value="${v}">${offerLabels[v]}</option>`).join('')}</select></div><div class="field" style="margin-top:10px"><label>理由</label><textarea id="offer-status-reason" class="textarea"></textarea></div><p class="subtle">Offer 接受不等于自动录用；录用仍需人工将候选人推进到“录用”阶段并完成最终决定。</p>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveOfferStatus('${oid}','${cid}')">保存</button>`);window.saveOfferStatus=async(oid,cid)=>{try{if(!$('#offer-status').value){toast('请选择合法的下一状态',true);return}await api(`/api/v1/offers/${oid}/status`,{method:'POST',body:JSON.stringify({status:$('#offer-status').value,reason:$('#offer-status-reason').value||'人工更新 Offer',actor:'human'})});toast('Offer 状态已更新');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
function candidateWorkspaceHtml(w,a){const fit=a?.fit_score==null?'待证据闭合':`${a.fit_score}%`;const cov=a?`${Math.round(Number(a.evidence_coverage||0)*100)}%`:'—';return `<div class="grid kpi" style="grid-template-columns:repeat(auto-fit,minmax(150px,1fr))"><div class="kpi-card"><div class="kpi-label">决策状态</div><div class="kpi-value" style="font-size:20px">${esc(w.readiness_label)}</div></div><div class="kpi-card"><div class="kpi-label">岗位匹配</div><div class="kpi-value" style="font-size:20px">${esc(fit)}</div></div><div class="kpi-card"><div class="kpi-label">证据覆盖</div><div class="kpi-value" style="font-size:20px">${esc(cov)}</div></div><div class="kpi-card"><div class="kpi-label">阻塞标准</div><div class="kpi-value">${w.blocking_count}</div></div><div class="kpi-card"><div class="kpi-label">当前决定</div><div class="kpi-value" style="font-size:20px">${esc(w.decision_label||'未决定')}</div></div></div>${a&&!a.publishable_for_comparison?`<p class="subtle">匹配分数尚不用于候选人比较：仍有未决标准、冲突或证据覆盖不足。缺失证据不会自动按“不满足”计分。</p>`:''}${w.stale_decision_id?`<div class="provider-card" style="margin:12px 0"><h3>历史决定已过期</h3><p class="subtle">上一决策上下文中的人工决定为 <strong>${esc(w.stale_decision_label)}</strong>。材料或招聘协议已经变化，因此该决定不会自动继续有效。</p><div class="quick-note">原理由：${esc(w.stale_decision_reason||'—')}</div><div class="actions" style="margin-top:10px"><button class="btn" onclick="openDecisionHistory('${w.candidate_id}')">查看决定历史</button><button class="btn primary" onclick="reaffirmHistoricalDecision('${w.candidate_id}')" ${w.decision_reaffirmable?'':'disabled title="当前证据尚不支持重申：请先核实关键评价标准"'}>按当前证据重申</button></div></div>`:''}<div class="actions" style="margin:10px 0 14px"><button class="btn small" onclick="openDecisionHistory('${w.candidate_id}')">决定 Lineage</button><button class="btn small" onclick="openCandidateAiRuns('${w.candidate_id}')">AI Run Ledger</button></div><h3>当前材料</h3>${(w.sources||[]).map(s=>`<div class="source-card"><div><strong>${esc(s.source_kind)}</strong> <span class="mono subtle">${esc(s.source_id)}</span> ${s.in_current_material?'<span class="status good">当前版本</span>':'<span class="status">历史材料</span>'}</div><div class="source-text">${esc(s.has_text?s.text_preview:'（二进制原始材料）')}</div><div class="actions"><button class="btn small" onclick="openSourceViewer('${s.source_id}')">Source Viewer</button><button class="btn small" onclick="openScoringView('${s.source_id}')" ${s.has_text?'':'disabled'}>隐私评分视图</button><button class="btn small" onclick="extractSource('${w.candidate_id}','${s.source_id}')" ${s.has_text&&s.in_current_material?'':'disabled'}>从此材料提取 Claim</button></div></div>`).join('')||'<div class="empty">暂无材料</div>'}<h3>AI / Source Claims</h3>${(w.claims||[]).map(c=>`<div class="claim ${c.confirmation_state}" id="srw-claim-${esc(c.claim_id)}"><div>${esc(c.normalized_text)}</div><div class="quick-note">状态：${esc(c.confirmation_state)} · Source ${esc(c.source_id)}</div><div class="actions" style="margin-top:8px"><button class="btn small" onclick="openClaimGrounding('${c.claim_id}')">定位原文</button>${c.confirmation_state==='unreviewed'?`<button class="btn small primary" onclick="reviewClaim('${c.claim_id}',true,'${w.candidate_id}')">确认事实</button><button class="btn small danger" onclick="reviewClaim('${c.claim_id}',false,'${w.candidate_id}')">拒绝提议</button>`:''}</div></div>`).join('')||'<div class="empty">尚无 Claim，可使用 AI 提取当前材料中的可定位事实。</div>'}<h3>评价标准与人工核实</h3><table class="table"><thead><tr><th>标准</th><th>状态</th><th>证据</th><th>缺口/核实问题</th><th></th></tr></thead><tbody>${(w.criteria||[]).map(c=>`<tr><td><strong>${esc(c.name)}</strong></td><td>${esc(c.status_label)} ${c.carried_forward?'<span class="status info">沿用已定位证据</span>':''}</td><td>${esc(c.evidence_label)}</td><td>${esc(c.gap||c.probe||'—')}</td><td><button class="btn small" onclick="openVerify('${w.candidate_id}','${esc(c.criterion_key)}','${esc(c.name)}')">人工核实</button></td></tr>`).join('')}</tbody></table><div class="divider"></div><div class="actions"><button class="btn primary" onclick="openDecision('${w.candidate_id}')" ${!w.decision_context_hash?'disabled title="必须先发布岗位标准与候选人材料"':''}>记录人工决定</button></div>`}
window.openSourceContent=async url=>{try{const d=await api(url);modal('完整材料原文',`<div class="codebox" style="white-space:pre-wrap;max-height:65vh;overflow:auto">${esc(d.text_content)}</div>`)}catch(e){toast(e.message,true)}};window.openScoringView=async sid=>{try{const d=await api(`/api/v1/sources/${sid}/scoring-view`);modal('隐私评分视图',`<p class="subtle">发送给远程文本 AI 的是这一份等长脱敏投影。姓名、电话、邮箱、证件号、精确地址等不会直接出站。</p><div class="pill-row">${Object.entries(d.redaction_counts||{}).map(([k,v])=>`<span class="status">${esc(k)} ${v}</span>`).join('')||'<span class="status good">未检测到需脱敏字段</span>'}</div><div class="codebox" style="white-space:pre-wrap;max-height:58vh;overflow:auto;margin-top:10px">${esc(d.text_content)}</div>`)}catch(e){toast(e.message,true)}};window.openClaimGrounding=async id=>{try{const d=await api(`/api/v1/claims/${id}/grounding`),l=d.locator||{};modal('Claim 原文定位',`<div class="quick-list"><div class="quick-item"><span>页码</span><strong>${esc(l.page??'—')}</strong></div><div class="quick-item"><span>字符范围</span><strong>${esc(`${l.char_start??'—'}–${l.char_end??'—'}`)}</strong></div><div class="quick-item"><span>PDF BBox</span><strong class="mono">${esc(l.bbox?JSON.stringify(l.bbox):'—')}</strong></div></div><div class="codebox" style="white-space:pre-wrap;margin-top:10px">${esc(l.quote||'')}</div>`,`<button class="btn" onclick="closeModal()">关闭</button><button class="btn primary" onclick="openSourceViewer('${d.source_id}','${l.page||1}','${d.claim_id}')">高亮打开 Source Viewer</button>`)}catch(e){toast(e.message,true)}};
window.cacheMaterialDraft=(cid,value)=>{if(!materialDrafts.has(cid)&&materialDrafts.size>=20)materialDrafts.delete(materialDrafts.keys().next().value);materialDrafts.set(cid,value)};
window.pasteMaterial=async cid=>{const text=materialDrafts.get(cid)??$('#paste-material')?.value??'';if(!text.trim()){toast('请先输入材料文本',true);return}try{await api(`/api/v1/candidates/${cid}/sources/text`,{method:'POST',body:JSON.stringify({text_content:text,filename:'pasted.txt',source_kind:'resume',publish_material:true})});if(materialDrafts.get(cid)===text)materialDrafts.delete(cid);toast('文本材料已发布');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.uploadCandidateFile=async cid=>{const f=$('#candidate-file').files[0];if(!f){toast('请选择文件',true);return}try{const r=await uploadFile(cid,f);toast(r.task_status?`文件已保存，任务状态：${r.task_status}`:'文件已导入');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.extractSource=async(cid,sid)=>{try{const r=await api(`/api/v1/candidates/${cid}/evidence/extract-task`,{method:'POST',body:JSON.stringify({source_id:sid})});if(r.task_status==='waiting_provider')toast('AI 提取任务已保存；配置文本 AI 后可在后台任务中直接重试',true);else toast(`AI 提取任务状态：${r.task_status}`);closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.extractAllClaims=async cid=>{try{const w=await api(`/api/v1/candidates/${cid}/workspace`);let queued=0;for(const s of w.sources||[]){if(!s.has_text||!s.in_current_material)continue;await api(`/api/v1/candidates/${cid}/evidence/extract-task`,{method:'POST',body:JSON.stringify({source_id:s.source_id})});queued++}toast(`已提交 ${queued} 个当前材料 AI 提取后台任务`);closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.reviewClaim=async(id,accepted,cid)=>{try{await api(`/api/v1/claims/${id}/review`,{method:'POST',body:JSON.stringify({accepted,actor:'human'})});toast(accepted?'已确认为事实':'已拒绝 AI 提议');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.openVerify=(cid,key,name)=>modal(`人工核实 · ${name}`,`<div class="form-grid"><div class="field"><label>状态</label><select id="v-status" class="select"><option value="met">满足</option><option value="partial">部分满足</option><option value="missing">缺失</option><option value="conflict">冲突</option><option value="not_met">不满足</option></select></div><div class="field"><label>证据强度</label><select id="v-evidence" class="select"><option value="strong">强</option><option value="medium">中</option><option value="weak">弱</option><option value="none">无</option></select></div><div class="field full"><label>理由</label><textarea id="v-reason" class="textarea"></textarea></div><div class="field full"><label>证据缺口</label><input id="v-gap" class="input"></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveVerify('${cid}','${key}')">保存人工核实</button>`);
window.saveVerify=async(cid,key)=>{try{await api(`/api/v1/candidates/${cid}/verifications`,{method:'POST',body:JSON.stringify({criterion_key:key,status:$('#v-status').value,evidence_level:$('#v-evidence').value,reason:$('#v-reason').value||'人工核实',note:$('#v-reason').value||'人工核实',gap:$('#v-gap').value,actor:'human'})});toast('人工核实已记录');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
window.openDecision=cid=>modal('记录人工决定',`<div class="field"><label>决定</label><select id="d-decision" class="select"><option value="advance">推进</option><option value="hold">暂缓</option><option value="reject">拒绝</option></select></div><div class="field" style="margin-top:10px"><label>决定理由</label><textarea id="d-reason" class="textarea"></textarea></div><p class="subtle">最终决定必须由人工明确提交；AI、OCR、ASR 不会代替此动作。</p>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveDecision('${cid}')">提交人工决定</button>`);
window.saveDecision=async cid=>{try{await api(`/api/v1/candidates/${cid}/decision`,{method:'POST',body:JSON.stringify({decision:$('#d-decision').value,reason:$('#d-reason').value||'人工决定',actor:'human'})});toast('人工决定已记录');closeModal();await candidateDrawer(cid)}catch(e){toast(e.message,true)}};
async function flowTab(el,p){let candidates=[];try{candidates=(await api(`/api/v1/projects/${state.projectId}/candidate-search?q=${encodeURIComponent(state.flowQuery)}&limit=20`)).candidates||[]}catch{};let cid=state.candidateId;if(cid&&!candidates.some(x=>x.candidate_id===cid)){try{const x=await api(`/api/v1/candidates/${cid}/summary`);candidates.unshift(x)}catch{cid=null}}if(!cid)cid=candidates[0]?.candidate_id;if(cid)state.candidateId=cid;if(!cid){el.innerHTML=`<div class="searchbar"><input id="flow-q" class="input" placeholder="搜索候选人"><button class="btn" onclick="flowSearchCandidates()">搜索</button></div><div class="empty"><strong>暂无匹配候选人</strong>通过姓名搜索候选人，而不是固定加载前 100/200 人。</div>`;return}const [ev,re,pipe]=await Promise.all([api(`/api/v1/candidates/${cid}/events`),api(`/api/v1/candidates/${cid}/reevaluations`),api(`/api/v1/candidates/${cid}/pipeline`)]);el.innerHTML=`<div class="panel-head" style="padding:0 0 12px;border:0"><div><h3>招聘流程 · ${stageLabel(pipe.current_stage)}</h3><div class="searchbar"><input id="flow-q" class="input" value="${esc(state.flowQuery)}" placeholder="搜索候选人"><button class="btn small" onclick="flowSearchCandidates()">搜索</button><select class="select" onchange="selectFlowCandidate(this)">${candidates.map(x=>`<option value="${x.candidate_id}" ${x.candidate_id===cid?'selected':''}>${esc(x.display_name)} · ${stageLabel(x.pipeline_stage)}</option>`).join('')}</select></div></div><div class="actions"><button class="btn" onclick="openContactWorkbench()">联系工作台</button><button class="btn" onclick="openPhoneScript('${cid}')">电话脚本</button><button class="btn" onclick="openEvent('${cid}','phone_screen')">＋ 电话筛选</button><button class="btn primary" onclick="openEvent('${cid}','interview')">＋ 面试排期</button><button class="btn" onclick="openReeval('${cid}')">＋ 复评草案</button></div></div><div class="two"><section><h3>面试 / 电话排期</h3>${ev.events.length?`<div class="timeline">${ev.events.map(x=>`<div class="timeline-item"><strong>${esc(x.title||x.event_type)} <span class="status ${statusClass(x.event_state)}">${esc(x.event_state)}</span></strong><small>${x.scheduled_at?new Date(x.scheduled_at).toLocaleString():new Date(x.created_at).toLocaleString()} · ${x.duration_minutes||0} 分钟 · ${esc(x.interviewer||'未指定')}</small><div>${esc(x.notes)}</div><div class="subtle">地点：${esc(x.location||'—')} · outcome：${esc(x.outcome||'—')}</div>${x.event_type==='interview'?`<div class="actions" style="margin-top:6px"><button class="btn small" onclick="openScorecards('${x.event_id}')">独立 Scorecard</button></div>`:''}${x.event_state==='scheduled'?`<div class="actions" style="margin-top:6px"><button class="btn small primary" onclick="completeEvent('${x.event_id}')">完成并提交结构化反馈</button><button class="btn small" onclick="cancelEvent('${x.event_id}')">取消</button></div>`:''}</div>`).join('')}</div>`:'<div class="empty">暂无电话/面试记录</div>'}</section><section><h3>复评草案</h3>${re.drafts.length?re.drafts.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.summary||'复评草案')}</div><div class="quick-note">${esc(x.state)} · ${new Date(x.created_at).toLocaleString()}</div></div>${x.state==='draft'?`<button class="btn small" onclick="applyReeval('${x.draft_id}')">查看/应用差异</button>`:''}</div>`).join(''):'<div class="empty">暂无复评草案</div>'}</section></div>`}
window.flowSearchCandidates=()=>{state.flowQuery=$('#flow-q')?.value||'';state.candidateId=null;projectWorkspace()};
window.openEvent=(cid,type)=>modal(type==='phone_screen'?'新增电话筛选 / 排期':'新增结构化面试',`<div class="form-grid"><div class="field"><label>标题</label><input id="e-title" class="input" value="${type==='phone_screen'?'电话筛选':'面试'}"></div><div class="field"><label>状态</label><select id="e-state" class="select"><option value="scheduled">已排期</option><option value="completed">已完成</option></select></div><div class="field"><label>计划时间</label><input id="e-time" class="input" type="datetime-local"></div><div class="field"><label>时长（分钟）</label><input id="e-duration" class="input" type="number" value="${type==='phone_screen'?30:60}"></div><div class="field"><label>面试官</label><input id="e-interviewer" class="input"></div><div class="field"><label>地点 / 会议链接</label><input id="e-location" class="input"></div><div class="field full"><label>结构化问题（每行：criterion_key | 问题 | 提问目的）</label><textarea id="e-questions" class="textarea" placeholder="experience | 请说明最近一次招聘项目 | 核实招聘经验"></textarea></div><div class="field full"><label>补充记录</label><textarea id="e-notes" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveEvent('${cid}','${type}')">保存</button>`);
function parseInterviewQuestions(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());return {criterion_key:a[0]||'',question:a[1]||a[0]||'',purpose:a[2]||''}})}
window.saveEvent=async(cid,type)=>{try{const time=$('#e-time').value;await api(`/api/v1/candidates/${cid}/events`,{method:'POST',body:JSON.stringify({event_type:type,title:$('#e-title').value,notes:$('#e-notes').value,scheduled_at:time?new Date(time).toISOString():'',duration_minutes:Number($('#e-duration').value||0),interviewer:$('#e-interviewer').value,location:$('#e-location').value,event_state:$('#e-state').value,metadata:{questions:parseInterviewQuestions($('#e-questions').value)}})});toast('流程记录已保存');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};
window.completeEvent=id=>modal('完成面试 / 电话筛选',`<div class="field"><label>Outcome</label><select id="event-outcome" class="select"><option value="proceed">建议推进</option><option value="hold">暂缓</option><option value="reject">建议拒绝</option><option value="completed">已完成</option></select></div><div class="field" style="margin-top:10px"><label>逐标准反馈（每行：criterion_key | rating | observation | supporting_evidence | counter_evidence | recommendation）</label><textarea id="event-feedback" class="textarea" placeholder="experience | strong | 说明了完整项目 | 招聘20人 | 无 | 进入下一轮"></textarea></div><div class="field" style="margin-top:10px"><label>总体建议</label><input id="event-overall" class="input" placeholder="advance / hold / reject"></div><div class="field" style="margin-top:10px"><label>记录</label><textarea id="event-notes" class="textarea"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveEventCompletion('${id}')">完成</button>`);
function parseInterviewFeedback(v){return String(v||'').split(/\n+/).map(x=>x.trim()).filter(Boolean).map(line=>{const a=line.split('|').map(x=>x.trim());return {criterion_key:a[0]||'',rating:a[1]||'unknown',observation:a[2]||'',supporting_evidence:a[3]||'',counter_evidence:a[4]||'',recommendation:a[5]||''}})}
window.saveEventCompletion=async id=>{try{const before=await api(`/api/v1/events/${id}`,{method:'PATCH',body:JSON.stringify({event_state:'completed',outcome:$('#event-outcome').value,notes:$('#event-notes').value,metadata:{feedback:parseInterviewFeedback($('#event-feedback').value),overall_recommendation:$('#event-overall').value}})});toast(before.source_id?'已完成并发布结构化面试 Source':'面试已完成');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};window.cancelEvent=async id=>{if(!confirm('取消该排期？'))return;try{await api(`/api/v1/events/${id}`,{method:'PATCH',body:JSON.stringify({event_state:'cancelled'})});toast('排期已取消');await projectWorkspace()}catch(e){toast(e.message,true)}};
window.openReeval=cid=>modal('创建复评草案',`<div class="field"><label>复评摘要</label><textarea id="r-summary" class="textarea"></textarea></div><div class="field" style="margin-top:10px"><label>提议说明（不会直接改人工决定）</label><textarea id="r-proposal" class="textarea"></textarea></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveReeval('${cid}')">创建草案</button>`);
window.saveReeval=async cid=>{try{await api(`/api/v1/candidates/${cid}/reevaluations`,{method:'POST',body:JSON.stringify({summary:$('#r-summary').value,proposal:{note:$('#r-proposal').value}})});toast('复评草案已创建');closeModal();await projectWorkspace()}catch(e){toast(e.message,true)}};window.applyReeval=async id=>{try{await api(`/api/v1/reevaluations/${id}/apply`,{method:'POST'});toast('草案已标记应用；人工决定未被修改');await projectWorkspace()}catch(e){toast(e.message,true)}};
async function qualityTab(el,p){const [idq,anchors,reviews]=await Promise.all([api(`/api/v1/projects/${state.projectId}/identity-reviews`),api(`/api/v1/projects/${state.projectId}/calibration/anchors`),api(`/api/v1/projects/${state.projectId}/calibration/reviews`)]);const all=idq.reviews||[],pending=all.filter(x=>x.status==='pending'),mergeReady=all.filter(x=>x.status==='confirmed_same'&&!x.merge_performed),merged=all.filter(x=>x.merge_performed);el.innerHTML=`<div class="two"><section><div class="panel-head" style="padding:0 0 10px;border:0"><h3>候选人身份复核</h3><button class="btn primary" onclick="scanIdentity()">扫描重复身份</button></div><p class="subtle">精确邮箱/电话只用于发现候选重复线索。必须先人工确认“同一人”，再进入 Merge Preview；系统不会静默自动合并。</p>${pending.length?pending.map(x=>`<div class="quick-item" id="srw-review-${esc(x.review_id)}"><div><div class="quick-title">${esc(x.candidate_a.display_name)} ↔ ${esc(x.candidate_b.display_name)}</div><div class="quick-note">${esc(x.match_reason)} · 待人工判定</div></div><div class="actions"><button class="btn small primary" onclick="resolveIdentity('${x.review_id}','confirmed_same')">同一人</button><button class="btn small" onclick="resolveIdentity('${x.review_id}','confirmed_distinct')">不同人</button></div></div>`).join(''):'<div class="empty">没有待处理的身份复核项</div>'}${mergeReady.length?`<h3 style="margin-top:16px">已确认同一人 · 待 canonical merge</h3>${mergeReady.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.candidate_a.display_name)} ↔ ${esc(x.candidate_b.display_name)}</div><div class="quick-note">历史数据不会被重写；合并前必须查看影响预览。</div></div><button class="btn small primary" onclick="openIdentityMerge('${x.review_id}','${x.candidate_a.candidate_id}','${x.candidate_b.candidate_id}')">Merge Preview</button></div>`).join('')}`:''}${merged.length?`<p class="subtle" style="margin-top:12px">已完成 canonical merge：${merged.length} 项。</p>`:''}</section><section><div class="panel-head" style="padding:0 0 10px;border:0"><h3>判断纠错队列</h3><button class="btn" onclick="openJudgmentReview()">＋ 记录纠错</button></div>${(reviews.reviews||[]).filter(x=>x.state==='open').length?(reviews.reviews||[]).filter(x=>x.state==='open').map(x=>`<div class="quick-item" id="srw-review-${esc(x.review_id)}"><div><div class="quick-title">${esc(x.criterion_key)} · ${esc(x.error_class)}${x.candidate_name?` · ${esc(x.candidate_name)}`:' · 项目级'}</div><div class="quick-note">${esc(x.before)} → ${esc(x.after)} · ${esc(x.reason)}</div></div><div class="actions">${x.candidate_id?`<button class="btn small" onclick="openCandidate('${x.candidate_id}')">查看候选人</button>`:''}<button class="btn small primary" onclick="resolveJudgmentReview('${x.review_id}')">完成复核</button></div></div>`).join(''):'<div class="empty">暂无开放的判断纠错项</div>'}</section></div><div class="divider"></div><section><div class="panel-head" style="padding:0 0 10px;border:0"><div><h3>Criterion Anchor Cases</h3><div class="subtle">observed → human_reviewed → candidate → gold；Gold 必须由第二位不同复核者晋级。</div></div><button class="btn primary" onclick="openCreateAnchor()">＋ 新建 Anchor</button></div>${(anchors.anchors||[]).length?`<table class="table"><thead><tr><th>标准</th><th>案例</th><th>期望判断</th><th>证据</th><th>生命周期</th><th></th></tr></thead><tbody>${anchors.anchors.map(x=>`<tr><td>${esc(x.criterion_key)}</td><td>${esc(x.case_text.slice(0,100))}</td><td>${esc(x.expected_judgment)}</td><td>${esc(x.expected_evidence_level)}</td><td><span class="status ${x.lifecycle==='gold'?'good':'info'}">${esc(x.lifecycle)}</span></td><td>${x.lifecycle!=='gold'?`<button class="btn small" onclick="promoteAnchor('${x.anchor_id}','${x.lifecycle}')">晋级</button>`:''}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">尚未建立校准 Anchor Case</div>'}</section>`}window.scanIdentity=async()=>{try{const r=await api(`/api/v1/projects/${state.projectId}/identity-reviews/scan`,{method:'POST',body:JSON.stringify({actor:'human'})});toast(`身份扫描完成：新增 ${r.created} 项`);await projectWorkspace()}catch(e){toast(e.message,true)}};window.resolveIdentity=async(id,status)=>{const note=prompt('复核说明：','人工核对联系方式与材料');if(note===null)return;try{await api(`/api/v1/identity-reviews/${id}/resolve`,{method:'POST',body:JSON.stringify({status,actor:'human',note})});toast(status==='confirmed_same'?'已确认同一人；请进入 Merge Preview 选择 canonical identity':'身份复核已记录');await projectWorkspace()}catch(e){toast(e.message,true)}};window.openJudgmentReview=()=>modal('记录判断纠错',`<div class="form-grid"><div class="field"><label>criterion_key</label><input id="jr-key" class="input"></div><div class="field"><label>触发场景</label><input id="jr-trigger" class="input" value="human_override"></div><div class="field"><label>原判断</label><input id="jr-before" class="input"></div><div class="field"><label>修正后</label><input id="jr-after" class="input"></div><div class="field full"><label>错误分类</label><select id="jr-reason" class="select"><option value="input_error">输入错误</option><option value="evidence_error">证据错误</option><option value="rubric_error">标准设计错误</option><option value="execution_error">执行错误</option><option value="decision_error">决策错误</option><option value="other">其他</option></select></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveJudgmentReview()">记录</button>`);window.saveJudgmentReview=async()=>{try{await api(`/api/v1/projects/${state.projectId}/calibration/reviews`,{method:'POST',body:JSON.stringify({trigger:$('#jr-trigger').value,criterion_key:$('#jr-key').value,before:$('#jr-before').value,after:$('#jr-after').value,reason:$('#jr-reason').value,actor:'human'})});closeModal();toast('判断纠错已进入复核队列');await projectWorkspace()}catch(e){toast(e.message,true)}};window.resolveJudgmentReview=async id=>{const note=prompt('复核结论 / 处理说明：','已复核并确认纠错处理');if(!note)return;try{await api(`/api/v1/calibration/reviews/${id}/resolve`,{method:'POST',body:JSON.stringify({actor:'human',note})});toast('判断纠错复核已完成');await projectWorkspace()}catch(e){toast(e.message,true)}};window.openCreateAnchor=()=>modal('新建 Criterion Anchor',`<div class="form-grid"><div class="field"><label>criterion_key</label><input id="an-key" class="input"></div><div class="field"><label>期望判断</label><select id="an-j" class="select">${['met','partial','missing','conflict','not_met'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>期望证据等级</label><select id="an-e" class="select">${['strong','medium','weak','none'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field full"><label>案例文本</label><textarea id="an-text" class="textarea"></textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveAnchor()">创建</button>`);window.saveAnchor=async()=>{try{await api(`/api/v1/projects/${state.projectId}/calibration/anchors`,{method:'POST',body:JSON.stringify({criterion_key:$('#an-key').value,case_text:$('#an-text').value,expected_judgment:$('#an-j').value,expected_evidence_level:$('#an-e').value,actor:'human'})});closeModal();toast('Anchor 已创建');await projectWorkspace()}catch(e){toast(e.message,true)}};window.promoteAnchor=async(id,current)=>{const order=['observed','human_reviewed','candidate','gold'],target=order[order.indexOf(current)+1],actor=prompt(target==='gold'?'Gold 晋级必须填写与首位复核者不同的复核人：':'复核人：','human');if(!actor)return;try{await api(`/api/v1/calibration/anchors/${id}/promote`,{method:'POST',body:JSON.stringify({target,actor})});toast(`Anchor 已晋级到 ${target}`);await projectWorkspace()}catch(e){toast(e.message,true)}};
async function auditTab(el,p){const limit=25;const d=await api(`/api/v1/projects/${state.projectId}/audit?limit=${limit}&offset=${state.auditOffset}`);el.innerHTML=`<div class="two"><div><h3>协议版本</h3><table class="table"><thead><tr><th>版本</th><th>状态</th><th>创建</th><th>Hash</th></tr></thead><tbody>${d.protocol_revisions.map(x=>`<tr><td>v${x.revision}</td><td><span class="status ${statusClass(x.state)}">${esc(x.state)}</span></td><td>${new Date(x.created_at).toLocaleString()}</td><td class="mono">${esc(x.content_hash.slice(0,12))}…</td></tr>`).join('')}</tbody></table></div><div><h3>审计时间线 <span class="subtle">${d.total} 项</span></h3>${d.audit_events.length?`<div class="timeline">${d.audit_events.map(x=>`<div class="timeline-item"><strong>${esc(x.event_type)}</strong><small>${esc(x.actor)} · ${new Date(x.created_at).toLocaleString()}</small><div class="subtle">${esc(x.reason||x.entity_type)}</div></div>`).join('')}</div>`:'<div class="empty">暂无审计事件</div>'}<div class="actions" style="justify-content:flex-end"><button class="btn small" ${d.offset<=0?'disabled':''} onclick="auditPage(-${limit})">上一页</button><button class="btn small" ${d.offset+d.limit>=d.total?'disabled':''} onclick="auditPage(${limit})">下一页</button></div></div></div>`}
window.auditPage=d=>{state.auditOffset=Math.max(0,state.auditOffset+d);projectWorkspace()};
async function refreshProjects(){const d=await api('/api/v1/projects');state.projects=d.projects||[]}
async function ensureProjects(){if(!state.projects.length){const d=await api('/api/v1/projects');state.projects=d.projects||[]}return state.projects}
function projectOptions(){return state.projects.map(p=>`<option value="${p.project_id}">${esc(p.title)} · ${esc(p.protocol_title||'')}</option>`).join('')}


window.openContactWorkbench=async()=>{try{const q=await api(`/api/v1/projects/${state.projectId}/contact-queue?limit=100&offset=0`);modal('联系工作台',`<p class="subtle" data-priority-semantics="contact_execution_priority_not_hiring_rank">联系优先级只用于执行安排，不是录用排序。</p><table class="table"><thead><tr><th>候选人</th><th>优先级</th><th>状态</th><th>下次联系</th><th>负责人</th><th></th></tr></thead><tbody>${q.candidates.map(x=>`<tr><td>${esc(x.display_name)}<div class="subtle">${esc(x.phone||x.email||'暂无已确认联系方式')}</div></td><td>${esc(x.priority)}</td><td>${esc(x.contact_status)}</td><td>${esc(x.next_contact_at||'未安排')}</td><td>${esc(x.owner||'未指定')}</td><td><button class="btn small" onclick="openActionPlan('${x.candidate_id}')">编辑行动</button><button class="btn small" onclick="openPhoneScript('${x.candidate_id}')">电话脚本</button></td></tr>`).join('')}</tbody></table>`,`<button class="btn" onclick="closeModal()">关闭</button>`)}catch(e){toast(e.message,true)}};
window.openActionPlan=async cid=>{try{const x=await api(`/api/v1/candidates/${cid}/action-plan`);modal('候选人行动计划',`<div class="form-grid"><div class="field"><label>联系优先级</label><select id="ap-priority" class="select">${['today','high','normal','low'].map(v=>`<option value="${v}" ${x.priority===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>负责人</label><input id="ap-owner" class="input" value="${esc(x.owner||'')}"></div><div class="field"><label>联系状态</label><select id="ap-status" class="select">${['to_contact','attempted','callback','contacted','not_interested','waiting_material','done'].map(v=>`<option value="${v}" ${x.contact_status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>下次联系时间</label><input id="ap-next" class="input" value="${esc(x.next_contact_at||'')}"></div><div class="field full"><label>原因 / 下一步</label><textarea id="ap-reason" class="textarea">${esc(x.reason||'')}</textarea></div></div>`,`<button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveActionPlan('${cid}')">保存</button>`)}catch(e){toast(e.message,true)}};
window.saveActionPlan=async cid=>{try{await api(`/api/v1/candidates/${cid}/action-plan`,{method:'PATCH',body:JSON.stringify({priority:$('#ap-priority').value,owner:$('#ap-owner').value,contact_status:$('#ap-status').value,next_contact_at:$('#ap-next').value,reason:$('#ap-reason').value,actor:'human'})});closeModal();toast('行动计划已保存');if(state.candidateId===cid)await candidateDrawer(cid);else await openContactWorkbench()}catch(e){toast(e.message,true)}};
window.openPhoneScript=async cid=>{try{const r=await api(`/api/v1/candidates/${cid}/phone-script`);modal('电话脚本 / 核实思路',`<p class="subtle">${esc(r.note)}</p><div class="quick-list">${r.questions.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.question)}</div><div class="quick-note">为什么问：${esc(x.purpose)}</div></div></div>`).join('')}</div>`,`<button class="btn" onclick="closeModal()">关闭</button>`)}catch(e){toast(e.message,true)}};
window.openScorecards=async eid=>{try{const r=await api(`/api/v1/events/${eid}/scorecards`);modal('独立 Interview Scorecard',`${r.scorecards.length?`<div class="quick-list">${r.scorecards.map(x=>`<div class="quick-item"><div><div class="quick-title">${esc(x.evaluator)} · ${esc(x.state)}</div><div class="quick-note">${esc(x.recommendation||'')}</div></div></div>`).join('')}</div>`:'<div class="empty">尚无评价者提交 Scorecard</div>'}<div class="divider"></div><div class="form-grid"><div class="field"><label>评价者</label><input id="sc-evaluator" class="input"></div><div class="field"><label>Criterion Key</label><input id="sc-key" class="input" placeholder="例如 comm"></div><div class="field"><label>Rating</label><select id="sc-rating" class="select"><option>strong</option><option>acceptable</option><option>concern</option><option>unknown</option></select></div><div class="field"><label>总体建议</label><input id="sc-rec" class="input"></div><div class="field full"><label>行为观察</label><textarea id="sc-observation" class="textarea"></textarea></div><div class="field"><label>支持证据</label><textarea id="sc-support" class="textarea"></textarea></div><div class="field"><label>反对证据</label><textarea id="sc-counter" class="textarea"></textarea></div></div><p class="subtle">不同评价者意见独立保存；系统不会自动平均成总分。</p>`,`<button class="btn" onclick="closeModal()">关闭</button><button class="btn primary" onclick="saveScorecard('${eid}')">提交并锁定</button>`)}catch(e){toast(e.message,true)}};
window.saveScorecard=async eid=>{try{await api(`/api/v1/events/${eid}/scorecards`,{method:'POST',body:JSON.stringify({evaluator:$('#sc-evaluator').value,feedback:[{criterion_key:$('#sc-key').value,rating:$('#sc-rating').value,observation:$('#sc-observation').value,supporting_evidence:$('#sc-support').value,counter_evidence:$('#sc-counter').value,recommendation:$('#sc-rec').value}],recommendation:$('#sc-rec').value,submit:true})});closeModal();toast('Scorecard 已独立提交并锁定')}catch(e){toast(e.message,true)}};
function candidateBriefHtml(r){const contact=r.contact||{},plan=r.action_plan||{},criteria=r.criteria||[],v=r.version_context||{};return `<div class="business-strip"><div><small>候选人</small><strong>${esc(r.display_name||'—')}</strong></div><div><small>当前阶段</small><strong>${esc(stageLabel(r.pipeline_stage))}</strong></div><div><small>联系方式</small><strong>${contact.user_confirmed?'已人工确认':'待确认'}</strong></div></div><div class="two"><section><h3>联系方式</h3><div class="quick-list"><div class="quick-item"><span>电话</span><strong>${esc(contact.phone||'未录入')}</strong></div><div class="quick-item"><span>邮箱</span><strong>${esc(contact.email||'未录入')}</strong></div></div></section><section><h3>当前行动计划</h3>${plan?`<div class="quick-list"><div class="quick-item"><span>优先级 / 负责人</span><strong>${esc(plan.priority||'normal')} · ${esc(plan.owner||'未指定')}</strong></div><div class="quick-item"><span>联系状态</span><strong>${esc(plan.contact_status||'to_contact')}</strong></div><div class="quick-item"><span>下次联系</span><strong>${esc(plan.next_contact_at||'未安排')}</strong></div></div><p class="subtle">${esc(plan.reason||'')}</p>`:'<div class="empty">暂无行动计划</div>'}</section></div><div class="divider"></div><h3>评价摘要</h3>${criteria.length?`<table class="table"><thead><tr><th>标准</th><th>判断</th><th>证据</th><th>理由 / 缺口</th></tr></thead><tbody>${criteria.map(x=>`<tr><td>${esc(x.criterion_key)}</td><td>${esc(x.status)}</td><td>${esc(x.evidence_level)}</td><td>${esc(x.reason||x.gap||'—')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">当前没有评价结果</div>'}<details style="margin-top:12px"><summary>审计上下文</summary><div class="codebox" style="margin-top:8px">${esc(JSON.stringify(v,null,2))}</div></details>`}
function handoffHtml(r){const rows=r.candidates||[];return `<div class="business-strip"><div><small>项目</small><strong>${esc(r.project_title||'—')}</strong></div><div><small>候选人</small><strong>${fmt(rows.length)}</strong></div><div><small>生成时间</small><strong style="font-size:14px">${r.generated_at?new Date(r.generated_at).toLocaleString():'—'}</strong></div></div><p class="subtle">交接视图聚焦阶段、联系方式、下一步和当前评价；完整版本上下文仍保留在下载的 JSON 中。</p>${rows.length?`<div class="quick-list">${rows.map(x=>{const contact=x.contact||{},plan=x.action_plan||{},criteria=x.criteria||[];const gaps=criteria.filter(c=>c.status==='missing'||c.status==='partial'||c.status==='conflict').length;return `<div class="quick-item" style="align-items:flex-start"><div style="flex:1"><div class="quick-title">${esc(x.display_name)} · ${esc(stageLabel(x.pipeline_stage))}</div><div class="quick-note">${esc(contact.phone||contact.email||'暂无联系方式')} · ${contact.user_confirmed?'联系方式已确认':'联系方式待确认'}</div><div class="quick-note">下一步：${esc(plan?.reason||plan?.contact_status||'未设置行动计划')} · 评价项 ${criteria.length} · 待核实/冲突 ${gaps}</div></div><button class="btn small" onclick="closeModal();openCandidate('${x.candidate_id}')">打开候选人</button></div>`}).join('')}</div>`:'<div class="empty">项目暂无候选人</div>'}`}
window.openCandidateBrief=async cid=>{try{const r=await api(`/api/v1/candidates/${cid}/brief`);modal('候选人简报',candidateBriefHtml(r),`<button class="btn" onclick="closeModal()">关闭</button><button class="btn primary" onclick="closeModal();openActionPlan('${cid}')">编辑下一步</button>`)}catch(e){toast(e.message,true)}};
window.openHandoff=async()=>{try{const r=await api(`/api/v1/projects/${state.projectId}/handoff`);state.handoffPayload=r;modal('项目交接摘要',handoffHtml(r),`<button class="btn" onclick="closeModal()">关闭</button><button class="btn primary" onclick="downloadHandoff()">下载完整交接 JSON</button>`)}catch(e){toast(e.message,true)}};
window.downloadHandoff=()=>{if(!state.handoffPayload)return;const raw=JSON.stringify(state.handoffPayload,null,2),blob=new Blob([raw],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`SRW_handoff_${state.projectId||'project'}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)};

init();

/* Core helpers published for the extracted domain modules (ADR-0002 split). */
window.head=head;window.statusClass=statusClass;window.stageLabel=stageLabel;window.workbenchActionLabel=workbenchActionLabel;window.ensureProjects=ensureProjects;window.refreshProjects=refreshProjects;window.projectOptions=projectOptions;window.stageLabels=stageLabels;window.offerLabels=offerLabels;window.projectStatusLabels=projectStatusLabels;window.icons=icons;window.criterionRow=criterionRow;